-- AQARI V267 Preview/Staging: expose exit notice through the existing official-document context contract.
do $r$ begin if to_regprocedure('public.aqari_official_document_context_pre_exit_20260915(uuid,text,uuid,uuid,jsonb)') is null then alter function public.aqari_official_document_context(uuid,text,uuid,uuid,jsonb) rename to aqari_official_document_context_pre_exit_20260915;end if;end $r$;
create or replace function public.aqari_official_document_context(p_workspace_id uuid,p_kind text,p_entity_id uuid default null,p_source_id uuid default null,p_fields jsonb default '{}') returns jsonb language plpgsql stable security definer set search_path='' as $$declare w uuid:=p_workspace_id;entities jsonb;defaults jsonb:='{}'::jsonb;begin if p_kind<>'exit_notice' then return public.aqari_official_document_context_pre_exit_20260915(p_workspace_id,p_kind,p_entity_id,p_source_id,p_fields);end if;if auth.uid() is null or not private.aqari_official_document_access(w,false) then raise insufficient_privilege using message='ACCESS_DENIED';end if;if p_source_id is not null or p_fields is null or jsonb_typeof(p_fields)<>'object' or octet_length(p_fields::text)>16000 then raise exception 'INVALID_DOCUMENT_REQUEST' using errcode='22023';end if;select coalesce(jsonb_agg(jsonb_build_object('id',l.id,'label',l.contract_no||' — '||q.full_name||' — '||p.name||' / '||u.unit_no) order by l.contract_no),'[]'::jsonb) into entities from public.aqari_leases l join public.aqari_tenants q on q.workspace_id=l.workspace_id and q.id=l.tenant_id join public.aqari_units u on u.workspace_id=l.workspace_id and u.id=l.unit_id join public.aqari_properties p on p.workspace_id=l.workspace_id and p.id=u.property_id join private.aqari_vacating_settlements s on s.workspace_id=l.workspace_id and s.lease_id=l.id where l.workspace_id=w and l.status in('signed','expired') and private.aqari_official_entity_scope(w,'lease',l.id,'read');if p_entity_id is not null then defaults:=private.aqari_official_source(w,'exit_notice','lease',p_entity_id,null,p_fields);end if;return jsonb_build_object('workspace_id',w,'user_id',auth.uid(),'kind','exit_notice','entity_type','lease','entity_id',p_entity_id,'source_id',null,'source_required',false,'entities',entities,'sources','[]'::jsonb,'defaults',defaults);end$$;
revoke all on function public.aqari_official_document_context(uuid,text,uuid,uuid,jsonb) from public,anon;grant execute on function public.aqari_official_document_context(uuid,text,uuid,uuid,jsonb) to authenticated;
